/**
 * Wire protocol version exchanged between qodercli (CLI) and
 * qoder-agent-sdk (SDK consumers).
 *
 * Hard-coded literal — decoupled from this SDK package's `version` so SDK
 * patches don't bump the wire. Bundlers inline it naturally; no `define`
 * substitution required.
 *
 * Bumping rules:
 *   - patch (1.0.0 → 1.0.1): doc/comment-only, no schema change
 *   - minor (1.0.0 → 1.1.0): add OPTIONAL fields or new message `type`s
 *   - major (1.x.y → 2.0.0): change semantics, remove fields, or change
 *     a discriminant. SDK runtime handshake refuses cross-major.
 *
 * The CLI announces its compiled-in `WIRE_PROTOCOL_VERSION` in the
 * `system/init` JSONL message. The SDK validates it against the
 * version it was built against using semver.
 */
export declare const WIRE_PROTOCOL_VERSION: "1.0.0";
export type WireProtocolVersion = string;